{
  "name": "Postman Builder",
  "slug": "{{bslug}}",
  "level": "location",
  "modules": [
    "enrollment.stores.enrolled_stores_control_panel",
    {
      "key": "catalog_pricing.products_rules.pre_enrollment",
      "mode": "rule"
    },
    {
      "key": "catalog_pricing.products_rules.warranty",
      "mode": "settings",
      "settings": [
        {
          "name": "Warranty enabled",
          "type": "boolean",
          "default": true
        },
        {
          "name": "Max days",
          "type": "number",
          "required": true,
          "default": 90
        },
        {
          "name": "Notes",
          "type": "text"
        },
        {
          "name": "Grade",
          "type": "radio",
          "default": "a",
          "options": [
            {
              "label": "A"
            },
            {
              "label": "B"
            },
            {
              "label": "C"
            }
          ]
        },
        {
          "name": "Coverage",
          "type": "dropdown",
          "library_id": "{{library_id}}"
        },
        {
          "name": "Region",
          "type": "dropdown",
          "options": [
            {
              "label": "North America"
            },
            {
              "label": "Europe",
              "code": "eu"
            }
          ]
        }
      ]
    }
  ]
}
